import redis, collections, sys, time
src0=redis.Redis(host='127.0.0.1',port=6379)
dst0=redis.Redis(host='127.0.0.1',port=6380)
assert dst0.info('keyspace') == {}, 'destination is not empty'
assert dst0.info('replication')['role']=='master'
counts=collections.Counter()

def stream_copy(s,d,k):
    info=s.xinfo_stream(k)
    entries=s.xrange(k, '-', '+')
    for id, fields in entries:
        args=[]
        for f,val in fields.items(): args.extend((f,val))
        d.execute_command('XADD',k,id,*args)
    # Preserve stream metadata (important for subsequent XADD and consumer lag).
    d.execute_command('XSETID',k,info['last-generated-id'],'ENTRIESADDED',info['entries-added'],'MAXDELETEDID',info['max-deleted-entry-id'])
    for group in s.xinfo_groups(k):
        g=group['name']
        d.execute_command('XGROUP','CREATE',k,g,'0-0')
        for c in s.xinfo_consumers(k,g):
            d.execute_command('XGROUP','CREATECONSUMER',k,g,c['name'])
        pending=s.xpending_range(k,g,'-','+',max(1,group['pending'])) if group['pending'] else []
        for p in pending:
            idle=max(0,int(p['time_since_delivered']))
            d.execute_command('XCLAIM',k,g,p['consumer'],0,p['message_id'],'IDLE',idle,'RETRYCOUNT',p['times_delivered'],'FORCE','JUSTID')
        opts=['ENTRIESREAD',group['entries-read']] if group.get('entries-read') is not None else []
        d.execute_command('XGROUP','SETID',k,g,group['last-delivered-id'],*opts)
        actual=d.xinfo_groups(k)[0] if len(s.xinfo_groups(k))==1 else next(x for x in d.xinfo_groups(k) if x['name']==g)
        assert actual['pending']==group['pending'], (k,g,actual,group)

for db in range(int(src0.config_get('databases')['databases'])):
    s=redis.Redis(host='127.0.0.1',port=6379,db=db)
    d=redis.Redis(host='127.0.0.1',port=6380,db=db)
    for k in s.scan_iter(count=500):
        typ=s.type(k)
        if typ == b'none': continue
        if typ==b'string': d.set(k,s.get(k))
        elif typ==b'hash':
            values=s.hgetall(k)
            if not values: continue
            d.hset(k,mapping=values)
            fields=list(values)
            expiries=s.execute_command('HPEXPIRETIME',k,'FIELDS',len(fields),*fields)
            for f,exp in zip(fields,expiries):
                if exp>0: d.execute_command('HPEXPIREAT',k,exp,'FIELDS',1,f)
        elif typ==b'list':
            values=s.lrange(k,0,-1)
            if values: d.rpush(k,*values)
        elif typ==b'set':
            values=s.smembers(k)
            if values: d.sadd(k,*values)
        elif typ==b'zset':
            values=s.zrange(k,0,-1,withscores=True)
            if values: d.zadd(k,{member:score for member,score in values})
        elif typ==b'stream': stream_copy(s,d,k)
        else: raise Exception(f'unknown type {db} {k!r} {typ}')
        exp=s.pexpiretime(k)
        if exp>0: d.pexpireat(k,exp)
        counts[(db,typ.decode())]+=1
    print('db',db,'source',s.dbsize(),'target',d.dbsize(),flush=True)
    assert s.dbsize()==d.dbsize(),db
print('copied',counts,flush=True)
